mapper.select:
SELECT

FROM game_stats s
LEFT JOIN user u ON s.userId = u.id AND u.isDelete = 0
WHERE s.gameType = #{gameType}
  AND s.isDelete = 0
  AND s.totalGames >= #{minGames}
ORDER BY
    CAST(JSON_EXTRACT(s.extraStats, CONCAT('$.', #{extKey})) AS DECIMAL(10, 4)) DESC,
    s.totalGames DESC
LIMIT #{limit}
